func TestIsRemoteConnectionType(t *testing.T) {
	tests := []struct {
		connectionType string
		expected       bool
	}{
		{"vscode-remote", true},
		{"kiro-remote", true},
		{"cursor-remote", true},
		{"windsurf-remote", true},
		{"web-ui", false},
		{"invalid-type", false},
		{"-remote", false},
		{"remote", false},
		{"", false},
	}

	for _, tt := range tests {
		t.Run(tt.connectionType, func(t *testing.T) {
			result := isRemoteConnectionType(tt.connectionType)
			if result != tt.expected {
				t.Errorf("isRemoteConnectionType(%q) = %v, want %v", tt.connectionType, result, tt.expected)
			}
		})
	}
}

func TestIsKnownRemoteType(t *testing.T) {
	tests := []struct {
		connectionType string
		expected       bool
	}{
		{"vscode-remote", true},
		{"kiro-remote", true},
		{"cursor-remote", true},
		{"windsurf-remote", false},
		{"web-ui", false},
	}

	for _, tt := range tests {
		t.Run(tt.connectionType, func(t *testing.T) {
			result := isKnownRemoteType(tt.connectionType)
			if result != tt.expected {
				t.Errorf("isKnownRemoteType(%q) = %v, want %v", tt.connectionType, result, tt.expected)
			}
		})
	}
}

content.data:
Because `isRemoteConnectionType` checks if a string ends with `-remote`. `web-ui` doesn't end with `-remote`, so it returns `false`. That's correct — `web-ui` is not a remote connection type, it's the browser-based connection.

The validation function handles `web-ui` separately as an exact match before it ever calls `isRemoteConnectionType`:

```go
switch {
case connectionType == connectionv1alpha1.ConnectionTypeWebUI:
    // valid
case isRemoteConnectionType(connectionType):
    // valid
default:
    // rejected
}
```

So `web-ui` passes validation, it just doesn't pass via the `isRemoteConnectionType` path.

input.oldStr:
// ConnectionTypeVSCodeRemote represents VSCode remote connection type
ConnectionTypeVSCodeRemote = "vscode-remote"
// ConnectionTypeWebUI represents web UI connection type
ConnectionTypeWebUI = "web-ui"

input.newStr:
// remoteConnectionTypeRegex validates the {ide}-remote pattern.
// Allows alphanumeric segments separated by single hyphens, ending with -remote.
// Valid: vscode-remote, my-vscode-remote, kiro-remote
// Invalid: -remote, my--vscode-remote, vscode-remote-ssh
var remoteConnectionTypeRegex = regexp.MustCompile(`^[a-zA-Z0-9]+(?:-[a-zA-Z0-9]+)*-remote$`)

// isRemoteConnectionType checks if the connection type follows the {ide}-remote pattern.
func isRemoteConnectionType(connectionType string) bool {
	return remoteConnectionTypeRegex.MatchString(connectionType)
}

input.oldStr:
// isRemoteConnectionType checks if the connection type follows the *-remote pattern.
func isRemoteConnectionType(connectionType string) bool {
	return strings.HasSuffix(connectionType, "-remote") && len(connectionType) > len("-remote")
}

