// remoteConnectionTypeRegex validates the {ide}-remote pattern.
// Allows alphanumeric segments separated by single hyphens, ending with -remote.
// Valid: vscode-remote, my-vscode-remote, kiro-remote
// Invalid: -remote, my--vscode-remote, vscode-remote-ssh
var remoteConnectionTypeRegex = regexp.MustCompile(`^[a-zA-Z0-9]+(?:-[a-zA-Z0-9]+)*-remote$`)

// isRemoteConnectionType checks if the connection type follows the {ide}-remote pattern.
func isRemoteConnectionType(connectionType string) bool {
	return remoteConnectionTypeRegex.MatchString(connectionType)
}

